    setCalenderOptions();
    var cal = new FullCalendar.Calendar(calendarEl, calenderOptions);
    cal.render();
    $parameters.TargetObject = calendarEl;
    $parameters.FullCalendarObject = cal;
}else{
    console.error("Target not Found!");
}

function setCalenderOptions(){
    if(AdvanceOpt.length > 0){
        var json = eval('(' + AdvanceOpt + ')');
        $actions.MergeJSONS(calenderOptions, json);
    }
    
    var callbackevents = addCallBackEvents();
    if(callbackevents !== null){
        $actions.MergeJSONS(calenderOptions, callbackevents);
    }
}

function addCallBackEvents(){
    var callbackEventsOptions = {};
    var isAllDisable = true;
    
    if($parameters.CB_Loading){
        callbackEventsOptions.loading = $actions.OnLoading;
        isAllDisable = false;
    }
    if($parameters.CB_EventDrop){
        callbackEventsOptions.eventDrop = $actions.OnEventDrop;
        isAllDisable = false;
    }
    if($parameters.CB_EventClick){
        callbackEventsOptions.eventClick = $actions.OnEventClick;
        isAllDisable = false;
    }
    if($parameters.CB_DateClick){
        callbackEventsOptions.dateClick = $actions.OnDateClick;
        isAllDisable = false;
    }
    if($parameters.CB_Select){
        callbackEventsOptions.select = $actions.OnSelect;
        isAllDisable = false;
    }
    if($parameters.CB_EventResize){
        callbackEventsOptions.eventResize = $actions.OnEventResize;
        isAllDisable = false;
    }
    if($parameters.CB_EventMouseEnter){
        callbackEventsOptions.eventMouseEnter = $actions.OnEventMouseEnter;
        isAllDisable = false;
    }
    if($parameters.CB_EventMouseLeave){
        callbackEventsOptions.eventMouseLeave = $actions.OnEventMouseLeave;
        isAllDisable = false;
    }
    if($parameters.CB_EventReceive){
        callbackEventsOptions.eventReceive = $actions.OnEventReceive;
        isAllDisable = false;
    }
    if($parameters.CB_datesRender){
        callbackEventsOptions.datesRender = $actions.OnDatesRender;
        isAllDisable = false;
    }

    if(isAllDisable){
        return null;
    }else{
        return callbackEventsOptions;
    }
}
};
});
